Aquí te presento una función en C++ que toma una referencia a un `std::string` que contiene texto con formato Markdown y devuelve un `std::string` que contiene texto con formato HTML:

```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <regex>

// Función para convertir Markdown a HTML
std::string markdownToHtml(const std::string& markdown) {
    // Mapa de correspondencias de Markdown a HTML
    std::unordered_map<std::string, std::string> markdownToHtmlMap = {
        {"# ", "<h1>"},
        {"## ", "<h2>"},
        {"### ", "<h3>"},
        {"#### ", "<h4>"},
        {"##### ", "<h5>"},
        {"###### ", "<h6>"},
        {"`", "<code>"},
        {"* ", "<em>"},
        {"** ", "<strong>"},
        {"*** ", "<b>"},
        {"[", "<a href='"],
        {"(", "<span class='math'>"],
        {"\\[", "<div class='math-display'>"],
        {"](", ")</span>"},
        {"])", ")</a>"},
        {"\\(", ")</span>"},
        {"\\]", ")</a>"},
        {"\\|", "<table><tr><td>"}, // Tabla
        {"\\| ", "</td><td>"},      // Celda de tabla
        {"\\|\\|", "</td></tr><tr><td>"}, // Fila de tabla
        {"\\|\\| ", "</td></tr></table>"}, // Final de tabla
        {"___", "<hr>"},
        {"---", "<hr>"},
        {"___", "<hr>"},
        {"** ", "<del>"},
        {"__ ", "<del>"},
        {"\\(", "</span>"},
        {"\\]", "</a>"},
        {">", "<blockquote>"}, // Citación
        {"  ", "&nbsp;"} // Espacio en blanco
    };

    // Expresión regular para extraer enlaces
    std::regex link_regex("\\[([^\\]]*)\\]\\([^\\)]*\\)");

    std::string html = "";
    std::string current_tag = "";
    bool in_math = false;
    bool in_table = false;

    for (char c : markdown) {
        std::string markdown_fragment = std::string(1, c);

        // Buscar correspondencias en el mapa
        auto it = markdownToHtmlMap.find(markdown_fragment);
        if (it != markdownToHtmlMap.end()) {
            if (!current_tag.empty()) {
                html += current_tag + "</" + current_tag.substr(1, current_tag.length() - 2) + ">";
                current_tag = "";
            }

            html += it->second;
        } else {
            if (c == '\\') {
                // Caracter especial
                markdown_fragment += markdown[++i];
            }

            if (markdown_fragment == "\\[" && !in_math) {
                // Comienzo de enlace
                std::smatch match;
                if (std::regex_match(markdown.substr(i), match, link_regex)) {
                    std::string link_text = match[1];
                    std::string link_url = match[0].substr(1, match[0].length() - 2);
                    html += "<a href='" + link_url + "'>" + link_text + "</a>";
                    i += match[0].length() - 1;
                } else {
                    html += markdown_fragment;
                }
            } else if (markdown_fragment == "\\(" && !in_table) {
                // Comienzo de matemáticas
                current_tag = "span class='math'";
                in_math = true;
            } else if (markdown_fragment == "\\)" && in_math) {
                // Fin de matemáticas
                current_tag = "";
                in_math = false;
                html += "</span>";
            } else if (markdown_fragment == "\\|" && !in_table) {
                // Comienzo de tabla
                html += "<table>";
                in_table = true;
            } else if (markdown_fragment == "\\|" && in_table) {
                // Nueva fila de tabla
                html += "</td></tr><tr><td>";
            } else if (markdown_fragment == "\\|\\|" && in_table) {
                // Nueva celda de tabla
                html += "</td><td>";
            } else if (markdown_fragment == "\\|\\|" && in_table) {
                // Fin de tabla
                html += "</td></tr></table>";
                in_table = false;
            } else {
                html += markdown_fragment;
            }
        }
    }

    // Añadir cierre de etiqueta si hay una etiqueta abierta al final
    if (!current_tag.empty()) {
        html += current_tag + "</" + current_tag.substr(1, current_tag.length() - 2) + ">";
        current_tag = "";
    }

    return html;
}

int main() {
    std::string markdown = "### H1\n"
                            "Este es un **texto** con enlace [Google](https://www.google.com/) y matemáticas \\(x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}\\). Además, aquí hay una tabla:\n"
                            "| Cabecera 1 | Cabecera 2 |\n"
                            "| ----------- | ----------- |\n"
                            "| Celda 1     | Celda 2     |\n"
                            "| Celda 3     | Celda 4     |";

    std::cout << markdownToHtml(markdown) << std::endl;

    return 0;
}
```

Este código define una función `markdownToHtml` que toma una referencia a un `std::string` que contiene texto con formato Markdown y devuelve un `std::string` con el mismo texto en formato HTML. La función usa una tabla de correspondencias para convertir los símbolos de Markdown a HTML. También usa expresiones regulares para detectar enlaces y caracteres especiales.

El código también incluye un ejemplo de uso en la función `main()` que toma un texto de ejemplo y muestra la salida HTML resultante.

